mapper.select:
select 
from ai_text_to_sql_eval_question q
where q.id = #{id}

select 
from ai_text_to_sql_eval_question q
where q.source_run_id = #{sourceRunId}

select 
from ai_text_to_sql_eval_question q


        and (
            q.question like concat('%', #{keyword}, '%')
            or q.judge_note like concat('%', #{keyword}, '%')
            or q.remark like concat('%', #{keyword}, '%')
        )


        and q.business_domain = #{businessDomain}


        and q.eval_target = #{evalTarget}


        and q.sample_category = #{sampleCategory}


        and q.source_type = #{sourceType}


        and q.status = #{status}


order by q.created_at desc, q.id desc

select 
from ai_text_to_sql_eval_question q
where q.status = 'ACTIVE'

    and q.business_domain = #{businessDomain}


    and q.eval_target = #{evalTarget}


    and q.sample_category = #{sampleCategory}

order by q.id asc

select from ai_text_to_sql_eval_question q where q.status = 'ACTIVE' and q.id in
#{id}
order by q.id asc
